        private static string GetCardImgPath(string CardValue)
        {
            string SkinPath = (_ImgPath == "") ? @"template/public/game_result/" : _ImgPath;
            string strCardImg = "";
            string[] strCard = CardValue.Split(',');
            for (int j = 0; j < strCard.Length; j++)
            {
                if (strCard[j].Contains("<br/>"))
                {
                    strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString().Replace("<br/>", "") + ".png' align='absmiddle' border='0' class='code' />";
                    strCardImg += "<br/>";
                }
                else
                {
                    strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString() + ".png' align='absmiddle' border='0' class='code' />";
                }

            }
            return strCardImg;
        }

        private static string GenImgUrl(string sMode, string sResult)
        {
            string sImgUrl = "";
            string skinroot_path = (_ImgPath == "") ? @"template\public\game_result\" : _ImgPath;

            if (sMode == "Roulette")
            {
                skinroot_path += @"Roulette\";
                sImgUrl = "<img  src=\"" + skinroot_path + sResult + ".png\"  align=\"absmiddle\" border=\"0\"  height=\"38\" width=\"38\"/>";
            }
            else if (sMode == "Sicbo")
            {
                skinroot_path += @"Sicbo\";
                string[] strResult = sResult.Split(';');
                string temp = "dice-";
                for (int j = 0; j < strResult.Length; j++)
                {
                    sImgUrl += "<img  src=\"" + skinroot_path + temp + strResult[j].ToString() + ".png\"  align=\"absmiddle\" border=\"0\" height=\"38\" width=\"38\" />";
                }
            }
            else if (sMode == "MoneyWheel")
            {
                skinroot_path += @"MoneyWheel\";
                string[] strResult = sResult.Split(':');
                var imageMapper = new Dictionary<string, string>
                {
                    {"0","bet-main-1-dim" },
                    {"1","bet-main-2-dim" },
                    {"2","bet-main-9-dim" },
                    {"3","bet-main-16-dim" },
                    {"4","bet-main-24-dim" },
                    {"5","bet-main-sa-gold-dim" },
                    {"6","bet-main-sa-black-dim" },
                    {"7","bet-sidebet-coin-result" },
                    {"8","bet-sidebet-prawn-result" },
                    {"9","bet-sidebet-crab" },
                    {"10","bet-sidebet-coin-result-2" },
                    {"11","bet-sidebet-hulu-result" },
                    {"12","bet-sidebet-chicken-result" },
                };
                for (int j = 0; j < strResult.Length; j++)
                {
                    var image = imageMapper.ContainsKey(strResult[j])?imageMapper[strResult[j]]: "notfound";
                    sImgUrl += "<img  src=\"" + skinroot_path + image + ".png\"  align=\"absmiddle\" border=\"0\"  height=\"38\" width=\"38\"/>";
                }
            }
            else
            {
                skinroot_path += @"FanTan\";
                var numberBall = int.Parse(sResult);
                for (int j = 0; j < numberBall; j++)
                {
                    sImgUrl += "<img  src=\"" + skinroot_path + "ball.png\"  align=\"absmiddle\" border=\"0\"  height=\"38\" width=\"38\"/>";
                }
            }

            return sImgUrl;
        }

